#!/usr/bin/env python3
"""Generate the per-tool files that point an AI assistant at the BA Pipeline core.

  python tools/adapters.py --target <project> [--tools claude,agents-md,copilot,cursor,gemini] [--dry-run]
  python tools/adapters.py --list

Adapters are thin: every generated file points at `.ba/core/` (the single source of truth), so a fix in the core
reaches every tool. The generator never destroys user content:
  * Files it owns carry a "generated by BA Pipeline" marker; it overwrites only those (or files that don't exist).
    An existing file without the marker is reported as "skipped (user file)" and left alone.
  * Shared instruction files (AGENTS.md, CLAUDE.md, GEMINI.md, .github/copilot-instructions.md) get a managed
    block between <!-- BA-PIPELINE:START --> and <!-- BA-PIPELINE:END -->; the rest of the file is kept. A block
    left by BA Copilot (the predecessor, BA-COPILOT markers) is replaced in place, and its renamed files removed.
  * .claude/settings.json is merged: the audit hook and deny rules are added once, nothing else is touched.
Running it twice changes nothing the second time.
"""

import argparse
import json
import re
import sys
from pathlib import Path

PACKAGE_DIR = Path(__file__).resolve().parent.parent
CORE = PACKAGE_DIR / "core"
VERSION = (PACKAGE_DIR / "VERSION").read_text(encoding="utf-8").strip() if (PACKAGE_DIR / "VERSION").is_file() else "0"

MARK = f"generated by BA Pipeline {VERSION} - do not edit; change .ba/core or .ba/local instead"
MARK_RX = re.compile(r"generated by BA (?:Pipeline|Guardian Angel|Copilot)")  # predecessors' files upgrade in place
BLOCK_START, BLOCK_END = "<!-- BA-PIPELINE:START -->", "<!-- BA-PIPELINE:END -->"
BLOCK_RX = re.compile(r"<!-- BA-(?:PIPELINE|GUARDIAN|COPILOT):START -->.*?<!-- BA-(?:PIPELINE|GUARDIAN|COPILOT):END -->\n?",
                      re.S)
RENAMED = {".cursor/rules/ba-copilot.mdc": ".cursor/rules/ba-pipeline.mdc",
           ".cursor/rules/ba-guardian.mdc": ".cursor/rules/ba-pipeline.mdc",
           ".kiro/steering/ba-copilot.md": ".kiro/steering/ba-pipeline.md",
           ".kiro/steering/ba-guardian.md": ".kiro/steering/ba-pipeline.md"}  # a predecessor's file -> its replacement
TOOLS = ("claude", "agents-md", "copilot", "cursor", "gemini", "kiro")
BA = "python .ba/tools/ba.py"   # python3 on macOS/Linux; MANUAL §0 explains

if hasattr(sys.stdout, "reconfigure"):
    sys.stdout.reconfigure(encoding="utf-8", errors="replace")


# --------------------------------------------------------------------------- core metadata

def write_lf(path, text):
    """Write UTF-8 text with LF line endings on every OS (Path.write_text only takes newline= from Python 3.10)."""
    with open(path, "w", encoding="utf-8", newline="\n") as handle:
        handle.write(text)


def frontmatter(path):
    text = path.read_text(encoding="utf-8")
    match = re.match(r"^---\n(.*?)\n---\n", text, re.S)
    meta = {}
    if match:
        for line in match.group(1).splitlines():
            if ":" in line:
                key, value = line.split(":", 1)
                meta[key.strip()] = value.strip()
    return meta


def stages():
    """[(name, description)] for every core stage, in workflow order."""
    order = ["ba-start", "ba-intake", "ba-elicit", "ba-scope", "ba-model", "ba-stories", "ba-ux", "ba-spec",
             "ba-review", "ba-handoff", "ba-refine", "ba-uat", "ba-release", "ba-docs", "ba-discover", "ba-change",
             "ba-next", "ba-step", "ba-profile", "ba-audit"]
    found = {p.stem: frontmatter(p) for p in sorted((CORE / "stages").glob("ba-*.md"))}
    names = [n for n in order if n in found] + sorted(n for n in found if n not in order)
    return [(n, found[n].get("description", n)) for n in names]


def reviewer():
    return frontmatter(CORE / "agents" / "requirements-reviewer.md")


def yaml_value(text):
    """Plain YAML scalar when safe, otherwise a double-quoted one (JSON strings are valid YAML)."""
    if ": " in text or " #" in text or re.match(r"^[\"'\[\]{}>|*&!%@`#,?:-]", text):
        return json.dumps(text, ensure_ascii=False)
    return text


def one_line(text, limit=160):
    text = " ".join(text.split())
    return text if len(text) <= limit else text[: limit - 3].rsplit(" ", 1)[0] + "..."


def stage_instruction(name):
    return (f"Read `.ba/core/MANUAL.md` (if it is not already in context), then follow "
            f"`.ba/core/stages/{name}.md` exactly for this request. Paths and commands are explained in "
            f"MANUAL §0.")


# --------------------------------------------------------------------------- writing

class Writer:
    def __init__(self, target, dry_run):
        self.target, self.dry_run, self.actions = target, dry_run, []

    def _write(self, rel, content, state):
        self.actions.append((state, rel))
        if not self.dry_run and state in ("created", "updated"):
            path = self.target / rel
            path.parent.mkdir(parents=True, exist_ok=True)
            write_lf(path, content)

    def owned(self, rel, content):
        """A file the generator owns entirely (must carry the marker)."""
        path = self.target / rel
        if not path.exists():
            return self._write(rel, content, "created")
        current = path.read_text(encoding="utf-8")
        if not MARK_RX.search(current):
            return self._write(rel, content, "skipped (user file)")
        self._write(rel, content, "unchanged" if current == content else "updated")

    def block(self, rel, body, title=None):
        """A managed block inside a file the user may also edit."""
        path = self.target / rel
        managed = f"{BLOCK_START}\n<!-- {MARK} -->\n{body.rstrip()}\n{BLOCK_END}\n"
        if not path.exists():
            content = (f"# {title}\n\n" if title else "") + managed
            return self._write(rel, content, "created")
        current = path.read_text(encoding="utf-8")
        if BLOCK_RX.search(current):
            content = BLOCK_RX.sub(lambda _: managed, current, count=1)
        else:
            content = current.rstrip() + "\n\n" + managed
        self._write(rel, content, "unchanged" if content == current else "updated")

    def retire(self, rel):
        """Remove a file an earlier version generated under another name (only if it carries the marker)."""
        path = self.target / rel
        if not path.is_file() or not MARK_RX.search(path.read_text(encoding="utf-8")):
            return
        self.actions.append(("removed (renamed)", rel))
        if not self.dry_run:
            path.unlink()

    def settings_json(self, rel, hook_command, deny):
        path = self.target / rel
        data = json.loads(path.read_text(encoding="utf-8-sig")) if path.exists() else {}
        before = json.dumps(data, sort_keys=True)
        perms = data.setdefault("permissions", {})
        rules = perms.setdefault("deny", [])
        for rule in deny:
            if rule not in rules:
                rules.append(rule)
        post = data.setdefault("hooks", {}).setdefault("PostToolUse", [])
        present = any(re.search(r'ba\.py"?\s+audit\s+hook', h.get("command", ""))
                      for group in post for h in group.get("hooks", []))
        if not present:
            post.append({"matcher": "Write|Edit|MultiEdit|NotebookEdit",
                         "hooks": [{"type": "command", "command": hook_command, "timeout": 30}]})
        state = "created" if not path.exists() else ("unchanged" if json.dumps(data, sort_keys=True) == before else "updated")
        self._write(rel, json.dumps(data, indent=2, ensure_ascii=False) + "\n", state)


# --------------------------------------------------------------------------- shared text

# Short and in the BA's own words: tools without slash commands match the request to a stage with this table.
STAGE_INTENTS = {
    "ba-start": "start a new feature, resume, \"where was I?\"",
    "ba-intake": "here are my notes, emails, documents, screenshots; which approach fits",
    "ba-elicit": "what am I missing? questions for stakeholders; here are the answers, \"done\"",
    "ba-scope": "problem, goals and success metrics, in/out of scope, MVP, PO confirmation",
    "ba-model": "process flows, states, data model, roles and permissions",
    "ba-stories": "epics, user stories, acceptance criteria, priorities",
    "ba-ux": "screens, wireframes, user journeys, prototype",
    "ba-spec": "business rules, data fields, messages, integrations, NFRs",
    "ba-review": "review my requirements, is this good enough? quality score",
    "ba-handoff": "hand off, package for PO, developers, QA, designers",
    "ba-refine": "backlog refinement, Definition of Ready, split stories, sprint preparation",
    "ba-uat": "test results, UAT, defect or requirement gap or change request, acceptance decision",
    "ba-release": "release notes, known issues, handover, KPIs, lessons learned",
    "ba-docs": "BRD, URD, user guide or user manual for end users; tài liệu BRD, URD, hướng dẫn sử dụng",
    "ba-discover": "new on the project, learn the existing system; mới vào dự án, tìm hiểu hệ thống cũ",
    "ba-change": "change request after drafting or approval, impact analysis",
    "ba-next": "what next? status",
    "ba-step": "an extra stage from a profile: vendor evaluation, threat model, cutover plan…",
    "ba-profile": "list, install or create approach profiles; change one feature's plan",
    "ba-audit": "who approved or decided what and when, why was it skipped, audit report",
}


def command_table():
    rows = "\n".join(f"| `{name}` | {STAGE_INTENTS.get(name) or one_line(desc.split('. ')[0], 90)} |"
                     for name, desc in stages())
    return ("Stage files: `.ba/core/stages/<stage>.md`. The BA doesn't need the command: match the request with "
            "`.ba/core/reference/routing.md` (English and Vietnamese examples); if two stages fit, ask one question "
            "with the options - never start a stage on a guess.\n\n| Stage | When the BA wants to… |\n|---|---|\n" + rows)


def common_body(tool_notes):
    return f"""## BA Pipeline — requirements workflow

This project uses **BA Pipeline** for business analysis. For any requirements work (features, notes, stories,
specs, reviews, handoff packs), act as the BA Pipeline assistant:

1. Read **`.ba/core/MANUAL.md`** first (§0 maps its terms to your tool), then follow the stage file below that
   fits the request. The BA may name it (`/ba-intake`, "run intake") or just describe the work.
2. Tooling: `{BA} <command>` (`python3` on macOS/Linux). `context <feature> <stage>` at the start of a
   stage (read it instead of whole files); one `turn <feature> --events …` at the end of every turn that changed
   something (`--gate` at the end of a stage); `answers new|read`, `questions archive`; `rtm`, `kpi`, `status`,
   `export` for the live traceability matrix, release KPIs, a plain-language status and Excel copies.
   Human gates are closed by the named approver, never by you (MANUAL §4a, §8).
3. Requirements live in `requirements/<feature>/`; `.ba/local/` overrides `.ba/core/`. Never edit `.ba/core/`
   or any `_audit/` log.

{tool_notes.strip()}

{command_table()}
"""


# --------------------------------------------------------------------------- adapters

def build_claude(w):
    w.block("CLAUDE.md", "@.ba/core/MANUAL.md\n\n" + common_body("""
**In Claude Code:** every stage is also a skill — `/ba-intake`, `/ba-review`, … (`.claude/skills/`). The
independent reviewer is the `requirements-reviewer` sub-agent. A post-edit hook records every file write in the
audit trail automatically; `ba turn` also records edits made outside
Claude Code. Agents and skills added during a session load in the next session.
"""), title="Project instructions")
    for name, desc in stages():
        w.owned(f".claude/skills/{name}/SKILL.md", f"""---
name: {name}
description: {yaml_value(desc)}
---
<!-- {MARK} -->

{stage_instruction(name)}
""")
    meta = reviewer()
    w.owned(".claude/agents/requirements-reviewer.md", f"""---
name: requirements-reviewer
description: {yaml_value(meta.get('description', 'Independent requirements reviewer'))}
tools: Read, Glob, Grep
---
<!-- {MARK} -->

Read `.ba/core/agents/requirements-reviewer.md` and follow it exactly — it defines your role, what to read, the
personas, severities and the return format. Conventions are in `.ba/core/MANUAL.md`. You did not write these
requirements; never edit any file.
""")
    hook = ('P=python3; command -v python3 >/dev/null 2>&1 || P=python; '
            '"$P" "$CLAUDE_PROJECT_DIR/.ba/tools/ba.py" audit hook')
    w.settings_json(".claude/settings.json", hook,
                    ["Edit(requirements/**/_audit/*.jsonl)", "Edit(audit/*.jsonl)", "Edit(audit/hook-errors.log)",
                     "Edit(.ba/core/**)"])


def build_agents_md(w):
    w.block("AGENTS.md", common_body("""
**Independent review:** use a sub-agent if your tool has one; otherwise ask the BA to open a new chat (or another
tool) with the prompt in MANUAL §7. **File audit:** if your tool has no post-edit hook wired to
`ba audit hook`, `ba turn` records file changes at the end of every turn.
"""), title="Agent instructions")


def build_copilot(w):
    w.block(".github/copilot-instructions.md", common_body("""
**In GitHub Copilot:** every stage is a prompt file — type `/ba-intake`, `/ba-review`, … in Copilot Chat
(`.github/prompts/`). The independent reviewer is the `requirements-reviewer` custom agent
(`.github/agents/`); where custom agents aren't available, review in a new chat with the prompt in MANUAL §7.
Copilot has no post-edit hook for the audit trail: `ba turn` records file changes at the end of every turn.
"""), title="Copilot instructions")
    for name, desc in stages():
        w.owned(f".github/prompts/{name}.prompt.md", f"""---
description: {yaml_value(one_line(desc, 200))}
mode: agent
---
<!-- {MARK} -->

{stage_instruction(name)}

Request: ${{input:request:What should this stage do? (feature, files, answers…)}}
""")
    w.owned(".github/agents/requirements-reviewer.agent.md", f"""---
description: {yaml_value(reviewer().get('description', 'Independent requirements reviewer'))}
---
<!-- {MARK} -->

You are the independent requirements reviewer. Read `.ba/core/agents/requirements-reviewer.md` and follow it
exactly. Conventions are in `.ba/core/MANUAL.md`. You did not write these requirements; never edit any file.
""")


def build_cursor(w):
    w.owned(".cursor/rules/ba-pipeline.mdc", f"""---
description: BA Pipeline requirements workflow - how to do business analysis work in this project
alwaysApply: true
---
<!-- {MARK} -->

{common_body('''
**In Cursor:** every stage is a command — type `/ba-intake`, `/ba-review`, … (`.cursor/commands/`). For the
independent review, open a new chat (or a background agent) with the prompt in MANUAL §7. Cursor's edits are not
recorded automatically: `ba turn` records them at the end of every turn.
''')}""")
    for name, desc in stages():
        w.owned(f".cursor/commands/{name}.md", f"""<!-- {MARK} -->
# {name}

{one_line(desc, 300)}

{stage_instruction(name)}
""")


def toml_string(text):
    return '"' + text.replace("\\", "\\\\").replace('"', '\\"') + '"'


def build_gemini(w):
    w.block("GEMINI.md", "@./.ba/core/MANUAL.md\n\n" + common_body("""
**In Gemini CLI:** every stage is a custom command — `/ba-intake`, `/ba-review`, … (`.gemini/commands/`). For the
independent review, start a new session with the prompt in MANUAL §7. With no post-edit hook, `ba turn`
records file changes at the end of every turn.
"""), title="Gemini instructions")
    for name, desc in stages():
        w.owned(f".gemini/commands/{name}.toml", f"""# {MARK}
description = {toml_string(one_line(desc, 200))}
prompt = \"\"\"
{stage_instruction(name)}

Request: {{{{args}}}}
\"\"\"
""")


def build_kiro(w):
    w.owned(".kiro/steering/ba-pipeline.md", f"""---
inclusion: always
---
<!-- {MARK} -->

{common_body('''
**In Kiro:** use a normal chat (Vibe) session for this workflow, not Spec mode — BA Pipeline has its own stages
and documents under `requirements/`. Pull a stage into the chat by typing `#ba-intake`, `#ba-review`, … (manual
steering files in `.kiro/steering/`), or just say "run intake". For the independent review, start a **new
session** with the prompt in MANUAL §7. Kiro's edits are not recorded automatically: `ba turn`
records them at the end of every turn.
''')}
The full manual: #[[file:.ba/core/MANUAL.md]]
""")
    for name, desc in stages():
        w.owned(f".kiro/steering/{name}.md", f"""---
inclusion: manual
---
<!-- {MARK} -->

# {name}

{one_line(desc, 300)}

{stage_instruction(name)}

#[[file:.ba/core/stages/{name}.md]]
""")


BUILDERS = {"claude": build_claude, "agents-md": build_agents_md, "copilot": build_copilot,
            "cursor": build_cursor, "gemini": build_gemini, "kiro": build_kiro}


def generate(target, tools, dry_run=False):
    writer = Writer(Path(target).resolve(), dry_run)
    for tool in tools:
        BUILDERS[tool](writer)
    for old, new in RENAMED.items():
        if any(rel == new for _, rel in writer.actions):
            writer.retire(old)
    return writer.actions


def main(argv=None):
    parser = argparse.ArgumentParser(prog="adapters", description="Generate BA Pipeline files for AI tools")
    parser.add_argument("--target", help="project root to write into")
    parser.add_argument("--tools", default="claude,agents-md", help=f"comma-separated: {','.join(TOOLS)} or all")
    parser.add_argument("--dry-run", action="store_true", help="show what would change, write nothing")
    parser.add_argument("--list", action="store_true", help="list tools and stages")
    args = parser.parse_args(argv)
    if args.list:
        print("tools: " + ", ".join(TOOLS))
        for name, desc in stages():
            print(f"  {name:11} {one_line(desc, 90)}")
        return 0
    if not args.target:
        parser.error("--target is required")
    tools = list(TOOLS) if args.tools == "all" else [t for t in re.split(r"\s*,\s*", args.tools) if t]
    unknown = [t for t in tools if t not in BUILDERS]
    if unknown:
        parser.error(f"unknown tools: {', '.join(unknown)}")
    actions = generate(args.target, tools, args.dry_run)
    for state, rel in actions:
        print(f"{state:22} {rel}")
    counts = {}
    for state, _ in actions:
        counts[state] = counts.get(state, 0) + 1
    print(("dry run: " if args.dry_run else "") + ", ".join(f"{n} {s}" for s, n in sorted(counts.items())))
    return 0


if __name__ == "__main__":
    sys.exit(main())
